output_text:
[
  {
    "id": "must_collect_cart_at_bay",
    "text": "A shopper is obliged to collect a cart from the entrance cart bay before completing the trip.",
    "abstraction": {
      "state_properties": {
        "cartBay": "at(1,7)"
      },
      "events": {
        "collectCart": {
          "pre": {
            "and": [
              "cartBay",
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "collectCart"
    }
  },
  {
    "id": "exit_requires_cart",
    "text": "It is forbidden to leave the store without still having the cart.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "broad_shelf_service_requires_cart",
    "text": "It is forbidden to interact with an ordinary shelf-service position in a broad aisle unless the shopper has the cart.",
    "abstraction": {
      "state_properties": {
        "broadAisle": {
          "ge": [
            "freeWidthH",
            2
          ]
        },
        "broadShelfServicePosition": {
          "and": [
            "adjShelf",
            "broadAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "broadShelfServicePosition",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_in_single_file_aisles",
    "text": "Carts are forbidden in single-file shelf aisles where shelves flank the shopper on both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "park_before_entering_single_file",
    "text": "On arriving with a cart at the mouth of a single-file shelf aisle, the shopper is obliged to park the cart before proceeding into that aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "arriveAtSingleFileMouthWithCart": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              },
              {
                "not": "singleFileAisleMouth"
              }
            ]
          },
          "post": "singleFileAisleMouth"
        },
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "singleFileAisleMouth",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "arriveAtSingleFileMouthWithCart",
      "discharge": "parkCart"
    }
  },
  {
    "id": "retrieve_cart_after_narrow_excursion",
    "text": "After returning from a single-file shelf aisle to its mouth without the cart, the shopper is obliged to retrieve the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "singleFileAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "returnToMouthWithoutCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "singleFileShelfAisle",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "singleFileAisleMouth"
        },
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "singleFileAisleMouth",
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "returnToMouthWithoutCart",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "cart_parking_only_at_aisle_mouths",
    "text": "It is forbidden to set down or abandon a cart except at the approved mouths of single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "approvedCartParkingPlace": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          {
            "not": "approvedCartParkingPlace"
          }
        ]
      }
    }
  },
  {
    "id": "no_unescorted_movement_outside_exceptions",
    "text": "Except while approaching the cart bay or making a narrow-aisle excursion from an approved cart-parking mouth, moving around the store without a cart is forbidden.",
    "abstraction": {
      "state_properties": {
        "cartAcquisitionZone": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "singleFileAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "allowedNoCartZone": {
          "or": [
            "cartAcquisitionZone",
            "singleFileShelfAisle",
            "singleFileAisleMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "or": [
              "N",
              "S",
              "E",
              "W"
            ]
          },
          {
            "not": "hasCart"
          },
          {
            "not": "allowedNoCartZone"
          }
        ]
      }
    }
  }
]
